insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('b3da9770-e9fc-426e-a6a2-910764fd59f4', 'd55f67d6-69aa-45d0-ab5c-05f56524d8cf', $$zuigflesje met gebogen vorm; foto$$,
   $$wiskunde-b-havo-2022-iii-zuigflesje-context1.png$$,
   $$Zuigflesjes voor baby’s hebben soms bijzondere vormen. Op de foto is goed de gebogen vorm van zo’n zuigflesje te zien.
foto$$, 'inline'),
  ('1511963c-b301-487b-9ad0-30d9af4a345a', 'd55f67d6-69aa-45d0-ab5c-05f56524d8cf', $$model (cm): bovenrand f(x) = −0,01x³ + 0,20x² − 1,06x + 6,44, onderrand g(x) = −0,01x³ + 0,16x² − 0,50x + 0,44 op 0 ≤ x ≤ 11; figuur 1; d(x) = f(x) − g(x)$$,
   $$wiskunde-b-havo-2022-iii-zuigflesje-context2.png$$,
   $$In deze opgave bekijken we een model van het vooraanzicht van het doorzichtige deel van het zuigflesje op de foto. In dit model zijn alle maten in cm.
In het model is de bovenrand van het zuigflesje de grafiek van een functie f, en de onderrand van het zuigflesje de grafiek van een functie g. De functies f en g worden voor 0 ≤ x ≤ 11 gegeven door:
f(x) = −0,01x³ + 0,20x² − 1,06x + 6,44
g(x) = −0,01x³ + 0,16x² − 0,50x + 0,44
In figuur 1 zijn de grafieken van f en g getekend.
figuur 1
De verticale afstand d(x) = f(x) − g(x) is niet voor elke waarde van x gelijk.$$, 'inline'),
  ('15fcdcdb-21e1-4236-9a81-d058925cd4cc', 'd55f67d6-69aa-45d0-ab5c-05f56524d8cf', $$gebogen lijn met maatstreepjes is grafiek van h; figuur 2; h(x) is het gemiddelde van f(x) en g(x)$$,
   $$wiskunde-b-havo-2022-iii-zuigflesje-context3.png$$,
   $$Op de foto is midden op het zuigflesje een gebogen lijn te zien. Hierop zijn maatstreepjes aangebracht. In het model is deze lijn de grafiek van een functie h. Zie figuur 2.
figuur 2
Voor elke x is h(x) het gemiddelde van f(x) en g(x).$$, 'inline'),
  ('e3379be7-83e3-4cda-aaff-1fb26ee5d08e', '02ec1a32-1e64-4501-a03b-360df09ebdb2', $$f(x) = −6/(2x − 3) + 2; l raaklijn in A(3, 0), m raaklijn in B(0, 4); figuur 1$$,
   $$wiskunde-b-havo-2022-iii-hyperbool-met-cirkels-context1.png$$,
   $$De functie f is gegeven door f(x) = −6/(2x − 3) + 2
Lijn l is de raaklijn aan de grafiek van f in het punt A(3, 0) en lijn m is de raaklijn aan de grafiek van f in het punt B(0, 4). Zie figuur 1.
figuur 1$$, 'inline'),
  ('c54a1b23-7f64-410b-989d-bb87faaf8d6a', '02ec1a32-1e64-4501-a03b-360df09ebdb2', $$beide raaklijnen hebben richtingscoëfficiënt 4/3$$,
   $$wiskunde-b-havo-2022-iii-hyperbool-met-cirkels-context2.png$$,
   $$De twee raaklijnen hebben allebei richtingscoëfficiënt 4/3$$, 'inline'),
  ('144289ef-f5ac-4f2d-a96c-a88f95b9c601', '02ec1a32-1e64-4501-a03b-360df09ebdb2', $$cirkel c₁ raakt l in A en raakt m; M₁ middelpunt van c₁; figuur 2$$,
   $$wiskunde-b-havo-2022-iii-hyperbool-met-cirkels-context3.png$$,
   $$Cirkel c₁ raakt l in A. Bovendien raakt c₁ aan m.
Punt M₁ is het middelpunt van c₁. Zie figuur 2.
figuur 2$$, 'inline'),
  ('c3e5fa80-13b1-4b87-b603-a06b97a85b80', '02ec1a32-1e64-4501-a03b-360df09ebdb2', $$M₁ = (27/25, 36/25)$$,
   $$wiskunde-b-havo-2022-iii-hyperbool-met-cirkels-context4.png$$,
   $$De coördinaten van M₁ zijn (27/25, 36/25).$$, 'inline'),
  ('f98dc6a9-37d2-4cfa-a05a-d2d856f4d848', '02ec1a32-1e64-4501-a03b-360df09ebdb2', $$M₁ ligt op k: y = (4/3)x; cirkel c₂: x² + y² − 3x − 4y = 0$$,
   $$wiskunde-b-havo-2022-iii-hyperbool-met-cirkels-context5.png$$,
   $$M₁ ligt op de lijn k met vergelijking y = (4/3)x
Cirkel c₂ is gegeven door de vergelijking x² + y² − 3x − 4y = 0$$, 'inline'),
  ('d747bbb0-1c68-4f55-aaa1-e5b89e157e97', '2db49f8d-3626-465e-b553-dcd09319a2fb', $$rendement van een warmtemotor: percentage van de energie dat wordt omgezet in bewegingsenergie$$,
   $$wiskunde-b-havo-2022-iii-het-rendement-van-warmtemotoren-context1.png$$,
   $$In een warmtemotor, bijvoorbeeld de motor van een auto, wordt de totale hoeveelheid energie die in brandstof aanwezig is nooit helemaal omgezet in bewegingsenergie. Het rendement van een warmtemotor is het percentage van de totale hoeveelheid energie dat wel wordt omgezet in bewegingsenergie.$$, 'inline'),
  ('adc31fe7-f2fc-4734-a62a-6bdc93b0fc15', '2db49f8d-3626-465e-b553-dcd09319a2fb', $$rendement van warmtemotoren neemt door technische vooruitgang toe$$,
   $$wiskunde-b-havo-2022-iii-het-rendement-van-warmtemotoren-context2.png$$,
   $$Door technische vooruitgang neemt het rendement van warmtemotoren toe. Men gaat ervan uit dat deze ontwikkeling zich de komende jaren blijft voortzetten.$$, 'inline'),
  ('2a237d7d-ab4b-471a-9570-8dbc121e3fe1', '2db49f8d-3626-465e-b553-dcd09319a2fb', $$formule (1): K = log(R/(100 − R)), R rendement in procenten$$,
   $$wiskunde-b-havo-2022-iii-het-rendement-van-warmtemotoren-context3.png$$,
   $$Om deze groei van het rendement in de tijd te onderzoeken, gebruikten de Amerikaan Ausubel en de Italiaan Marchetti de formule
K = log(R/(100 − R)) (1)
Hierin is R het rendement in procenten.$$, 'inline'),
  ('fa5472d2-32d6-46c5-b229-4d3fb3a46926', '2db49f8d-3626-465e-b553-dcd09319a2fb', $$figuur: K uitgezet tegen het jaartal van uitvinding voor verschillende warmtemotoren (ook op de uitwerkbijlage)$$,
   $$wiskunde-b-havo-2022-iii-het-rendement-van-warmtemotoren-context4.png$$,
   $$In de figuur hieronder, afkomstig uit een artikel van Ausubel en Marchetti, is voor verschillende warmtemotoren (vaak aangeduid met de naam van de uitvinder) K uitgezet tegen het jaartal waarin deze uitgevonden zijn. Deze figuur staat ook op de uitwerkbijlage.
figuur$$, 'inline'),
  ('fe942526-0b2f-4c36-86ce-6faf28d240c4', '2db49f8d-3626-465e-b553-dcd09319a2fb', $$warmtemotor van Charles Parsons (begin 20e eeuw) had zeer hoog rendement$$,
   $$wiskunde-b-havo-2022-iii-het-rendement-van-warmtemotoren-context5.png$$,
   $$In de figuur is te zien dat de warmtemotor die Charles Parsons aan het begin van de twintigste eeuw ontwikkelde een – voor die tijd – zeer hoog rendement had.$$, 'inline'),
  ('f501f741-d193-4ea0-860b-688d86b72819', '2db49f8d-3626-465e-b553-dcd09319a2fb', $$lijn in de figuur: formule (2) K = 0,00667t − 2, t jaren na 1700$$,
   $$wiskunde-b-havo-2022-iii-het-rendement-van-warmtemotoren-context6.png$$,
   $$In de figuur is een lijn weergegeven die de ontwikkeling van het rendement van warmtemotoren benadert. Bij deze lijn hoort de formule
K = 0,00667t − 2 (2)
Hierin is t het aantal jaren na 1700.$$, 'inline'),
  ('73e21b1c-666a-43c7-8aed-3c2bb52a4ac0', '2db49f8d-3626-465e-b553-dcd09319a2fb', $$in de toekomst rendement van 70% haalbaar$$,
   $$wiskunde-b-havo-2022-iii-het-rendement-van-warmtemotoren-context7.png$$,
   $$Men gaat ervan uit dat in de toekomst een rendement van 70% haalbaar is.$$, 'inline'),
  ('a3f78480-e7d2-474f-8401-e05e798d39a9', '2db49f8d-3626-465e-b553-dcd09319a2fb', $$met formules (1) en (2) R uitdrukken in t$$,
   $$wiskunde-b-havo-2022-iii-het-rendement-van-warmtemotoren-context8.png$$,
   $$Met behulp van formules (1) en (2) kan R uitgedrukt worden in t.$$, 'inline'),
  ('a7ddab68-c080-4e35-a4a1-0db34f6cfcff', '359d22c8-20b6-40c5-af3c-9265d3907503', $$f(x) = 2cos(3x) op [0, 3]; A meest linkse snijpunt van f met y = √3; k lijn door O en A; figuur 1$$,
   $$wiskunde-b-havo-2022-iii-cosinus-en-lijnen-context1.png$$,
   $$Op het domein [0, 3] is de functie f gegeven door f(x) = 2cos(3x). Het punt A is het meest links gelegen snijpunt van de grafiek van f en de lijn met vergelijking y = √3.
Lijn k gaat door O en A. Zie figuur 1.$$, 'inline'),
  ('3c3ac6b9-72c4-47b0-99ce-4490b22814fd', '359d22c8-20b6-40c5-af3c-9265d3907503', $$richtingscoëfficiënt van k is 18√3/π$$,
   $$wiskunde-b-havo-2022-iii-cosinus-en-lijnen-context2.png$$,
   $$De richtingscoëfficiënt van k is 18√3/π
figuur 1$$, 'inline'),
  ('b9476131-a64a-47bf-a4df-6dafa745e25a', '359d22c8-20b6-40c5-af3c-9265d3907503', $$T meest rechts gelegen top van f; l lijn door O en T; figuur 2$$,
   $$wiskunde-b-havo-2022-iii-cosinus-en-lijnen-context3.png$$,
   $$Het punt T is de meest rechts gelegen top van de grafiek van f. Lijn l gaat door O en T. Zie figuur 2.
figuur 2$$, 'inline'),
  ('20947ccc-65aa-4613-ad18-4ba12ad6a3c2', '49925fd7-8322-41ed-b07b-ef9aafca5183', $$f(x) = √x; A(1, 1); k horizontale lijn door A snijdt de y-as in S$$,
   $$wiskunde-b-havo-2022-iii-wortelfunctie-context1.png$$,
   $$De functie f is gegeven door f(x) = √x. Het punt A(1, 1) ligt op de grafiek van f.
Lijn k is de horizontale lijn door A. Deze lijn snijdt de y-as in het punt S.$$, 'inline'),
  ('ec461b09-18e4-476b-ba4a-cc181b2cdd29', '49925fd7-8322-41ed-b07b-ef9aafca5183', $$g gaat door midden M van AS en ontstaat uit f door vermenigvuldiging t.o.v. de x-as én t.o.v. de y-as; l verticale lijn door A snijdt g in N; figuur 1$$,
   $$wiskunde-b-havo-2022-iii-wortelfunctie-context2.png$$,
   $$We bekijken nu een functie g met de volgende kenmerken: – de grafiek van g gaat door het midden M van lijnstuk AS; – de grafiek van g kan uit de grafiek van f ontstaan door middel van een vermenigvuldiging ten opzichte van de x-as; – de grafiek van g kan ook uit de grafiek van f ontstaan door middel van een vermenigvuldiging ten opzichte van de y-as. Lijn l is de verticale lijn door A. Deze lijn snijdt de grafiek van g in het punt N. Zie figuur 1.
figuur 1$$, 'inline'),
  ('4dadc85b-a2dd-4510-8984-dbd8f80eeb56', '49925fd7-8322-41ed-b07b-ef9aafca5183', $$B(b, √b) met b > 0 op de grafiek van f met OA = AB; figuur 2$$,
   $$wiskunde-b-havo-2022-iii-wortelfunctie-context3.png$$,
   $$Punt B(b, √b), met b > 0 ligt op de grafiek van f, zodanig dat OA = AB. Zie figuur 2.
figuur 2$$, 'inline'),
  ('dc20df5c-5935-41a5-bd81-c7632f117048', '0cb0af83-f889-408f-8dbb-5049c3d1f2a5', $$boogbrug; onderrand van de boog benaderd met een wiskundig model; foto$$,
   $$wiskunde-b-havo-2022-iii-brug-context1.png$$,
   $$Op de foto is een boogbrug te zien. De vorm van de onderrand van de boog van de brug wordt benaderd met behulp van een wiskundig model.
foto$$, 'inline'),
  ('d75e2fdd-cdb6-439d-8927-b1668f35d7cb', '0cb0af83-f889-408f-8dbb-5049c3d1f2a5', $$schematische figuur van de onderrand van de boog$$,
   $$wiskunde-b-havo-2022-iii-brug-context2.png$$,
   $$In de figuur hieronder is de onderrand van de boog schematisch weergegeven.
figuur$$, 'inline'),
  ('d06256a0-2f58-4d45-ae3d-3f4b8b79cffc', '0cb0af83-f889-408f-8dbb-5049c3d1f2a5', $$x lengte langs het wegdek (m), y hoogte (m); P bij x = 1,4, Q bij x = 12,0, top T(4,1; 2,4); y = a(x + b + c/x)$$,
   $$wiskunde-b-havo-2022-iii-brug-context3.png$$,
   $$In deze figuur is x de lengte in meters van het wegdek gemeten vanaf het meest linkse punt van de brug en y de hoogte in meters van de onderrand van de boog ten opzichte van het wegdek. We nemen aan dat de onderrand van de boog begint en eindigt op het wegdek.
De onderrand van de boog begint bij x = 1,4 in punt P en eindigt bij x = 12,0 in punt Q. Het hoogste punt is T bij x = 4,1 en y = 2,4.
De boog kan benaderd worden met een formule van de vorm
y = a(x + b + c/x).$$, 'inline'),
  ('9fb8909f-d180-461f-9786-9f48c682d99c', 'cae4d28c-4ec2-47f4-8fc7-8e9f13fa2df0', $$ingeschreven cirkel van driehoek ABC met middelpunt M en straal r; figuren 1 en 2$$,
   $$wiskunde-b-havo-2022-iii-ingeschreven-cirkel-context1.png$$,
   $$De ingeschreven cirkel van een driehoek ABC is de cirkel die raakt aan alle zijden van de driehoek. Het punt M is het middelpunt van deze cirkel en r is de straal van deze cirkel. Zie figuur 1.
figuur 1 figuur 2$$, 'inline'),
  ('785aafac-d1ef-4a56-b5ec-0c7ee7e7ec76', 'cae4d28c-4ec2-47f4-8fc7-8e9f13fa2df0', $$verdeling in driehoeken AMB, BMC, AMC met hoogte r; oppervlakte G uitgedrukt in omtrek P en r: G = ½ · P · r$$,
   $$wiskunde-b-havo-2022-iii-ingeschreven-cirkel-context2.png$$,
   $$Elke driehoek ABC kan met behulp van punt M in drie aparte driehoeken AMB, BMC en AMC worden verdeeld. Zie figuur 2.
Wanneer we de zijden AB, BC en AC als basis kiezen voor respectievelijk de driehoeken AMB, BMC en AMC, dan is r de bijbehorende hoogte van elk van deze driehoeken. Voor elke driehoek ABC kan de oppervlakte G daarom worden uitgedrukt in de omtrek P van de driehoek en de straal r van de ingeschreven cirkel van de driehoek.
Er geldt: G = ½ · P · r$$, 'inline'),
  ('b32649a1-420c-444d-8282-1d4971500bae', 'cae4d28c-4ec2-47f4-8fc7-8e9f13fa2df0', $$driehoek ABC met AB = 14, BC = 13, AC = 15$$,
   $$wiskunde-b-havo-2022-iii-ingeschreven-cirkel-context3.png$$,
   $$We bekijken nu een driehoek ABC met zijden AB = 14, BC = 13 en AC = 15.$$, 'inline'),
  ('d6ce90c8-269d-4938-99c8-6904337f1d15', '0a746864-0a2c-4b3c-9d67-3bf94216c2a9', $$f(x) = (1/9) · (3⁻ˣᐟ² + 27); figuur; op domein [a, −4] is het bereik [4, 16]; a ≈ −8,67$$,
   $$wiskunde-b-havo-2022-iii-exponentiele-functie-context1.png$$,
   $$De functie f is gegeven door f(x) = (1/9) · (3⁻ˣᐟ² + 27). Zie de figuur.
figuur
Op het domein [a, −4] is het bereik van f gelijk aan [4, 16].
Er geldt, afgerond op twee decimalen: a ≈ −8,67$$, 'inline'),
  ('ccd46bba-709d-41d0-88ee-d471aaa437f1', '0a746864-0a2c-4b3c-9d67-3bf94216c2a9', $$ander voorschrift: f(x) = (1/√3)ˣ⁺⁴ + 3$$,
   $$wiskunde-b-havo-2022-iii-exponentiele-functie-context2.png$$,
   $$Een ander functievoorschrift voor f is f(x) = (1/√3)ˣ⁺⁴ + 3$$, 'inline');

