   $$wiskunde-b-havo-2022-iii-zuigflesje-vraag2.png$$, $$3p 2 Geef een functievoorschrift van h. Schrijf dit functievoorschrift zo eenvoudig mogelijk.$$, array['1511963c-b301-487b-9ad0-30d9af4a345a', '15fcdcdb-21e1-4236-9a81-d058925cd4cc']::uuid[]),
