   $$wiskunde-b-havo-2022-iii-hyperbool-met-cirkels-vraag4.png$$, $$5p 4 Bewijs dit.$$, array['e3379be7-83e3-4cda-aaff-1fb26ee5d08e', 'c54a1b23-7f64-410b-989d-bb87faaf8d6a', '144289ef-f5ac-4f2d-a96c-a88f95b9c601', 'c3e5fa80-13b1-4b87-b603-a06b97a85b80']::uuid[]),
  ('a69f6c20-dc8e-41c6-8252-38ef794cbdc0', '02ec1a32-1e64-4501-a03b-360df09ebdb2', 5,
